const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const newAddr = JSON.stringify({address1: '5000 Oak Hill Pkwy', address2: '', city: 'Austin', state: 'TX', country: 'USA', zip: '78735'});
