node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

const reminderId = crypto.randomUUID();
const currentTime = '2026-09-08T10:00:00';
const creationTs = Math.floor(new Date('2026-09-08T10:00:00Z').getTime() / 1000);
const reminderTs = Math.floor(new Date('2026-09-15T10:00:00Z').getTime() / 1000);

const stmt = db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, NULL, NULL, ?)');
stmt.run(
  reminderId,
  'Verify new default retail address at 5000 Oak Hill Pkwy, Austin, TX 78735.',
  creationTs,
  reminderTs,
  currentTime
);

console.log('Reminder created with ID:', reminderId);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log(JSON.stringify(row, null, 2));
"
